class ItemCollection {
  private items: string[] = [];
  add(item: string) { this.items.push(item); }
  createIterator() { return new ItemIterator(this.items); }
}

class ItemIterator {
  private index = 0;
  constructor(private items: string[]) {}
  hasNext() { return this.index < this.items.length; }
  next() { return this.items[this.index++]; }
}

class OrderRepository {
  private orders: Order[] = [];
  private cursor = 0;

  add(order: Order) { this.orders.push(order); }
  nextOrder() { return this.orders[this.cursor++]; }
}

