class Customers {
  constructor(private customers: Customer[]) {}
  createTraversal() { return new CustomersTraversal(this.customers); }
}
class CustomersTraversal {
  private i = 0;
  constructor(private list: Customer[]) {}
  hasNext() { return this.i < this.list.length; }
  next() { return this.list[this.i++]; }
}

